<script setup lang="ts">import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api}from'../../api/client';import type{SupportCase}from'../../domain/types';const c=ref<SupportCase|null>(null),loading=ref(false),error=ref('');async function refresh(){loading.value=true;error.value='';try{c.value=await api.getSupportCase()}catch{error.value='案件读取失败；已保留当前材料，可只读重试或安全离开。'}finally{loading.value=false}}onLoad(refresh)</script>
<template><view class="page"><AppHeader left="← 返回" right="订单" @left="uni.navigateBack()" @right="uni.navigateTo({url:'/pages/order/list'})"/><view class="content"><text class="kicker">客服与申诉 / UX-P030</text><view class="heading" role="heading" aria-level="1">我们会继续跟进</view><text class="desc">已确认事实与未知项分开显示；客服不会改写资金事实或承诺未批准时限。</text><StatusNotice v-if="error" tone="risk" title="读取错误">{{error}}</StatusNotice><view class="card"><text class="card-title">案件摘要</text><view class="kv"><text>SupportRef</text><text>{{c?.supportRef||'UNKNOWN'}}</text></view><view class="kv"><text>已确认事实</text><text>{{c?.confirmed||'UNKNOWN'}}</text></view><view class="kv"><text>未知项</text><text>{{c?.unknown||'UNKNOWN'}}</text></view><view class="kv"><text>当前责任</text><text>{{c?.responsibility||'公司继续查询'}}</text></view><view class="kv"><text>下一复核点</text><text>{{c?.nextReviewAt||'尚未确定'}}</text></view></view><view class="notice">客服首响、退款时限、通知频率和赔付金额仍为 UNKNOWN。</view></view><view class="action"><button class="primary" :disabled="loading" @click="refresh">只读重试案件查询</button><button class="secondary" @click="uni.reLaunch({url:'/pages/index/index'})">安全离开</button></view></view></template><style src="../../styles/shared.css"></style><style scoped>.notice{margin-top:24rpx;padding:22rpx;border-radius:20rpx;background:#fff8f1;color:#71411c}</style>
